WITH daily_brand AS ( SELECT cr.cr_returned_date_sk AS returned_date, i.i_brand AS brand, td.t_hour AS hour_of_day, SUM(cr.cr_net_loss) AS daily_brand_net_loss, cust.c_customer_id AS refunded_customer_id FROM catalog_returns cr JOIN item i ON cr.cr_item_sk = i.i_item_sk JOIN time_dim td ON cr.cr_returned_time_sk = td.t_time_sk JOIN customer cust ON cr.cr_refunded_customer_sk = cust.c_customer_sk WHERE cr.cr_return_amount > 0 GROUP BY cr.cr_returned_date_sk, i.i_brand, td.t_hour, cust.c_customer_id ) SELECT returned_date, brand, hour_of_day, daily_brand_net_loss, AVG(daily_brand_net_loss) OVER (PARTITION BY returned_date, brand ORDER BY hour_of_day ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS moving_avg_net_loss, CASE WHEN daily_brand_net_loss > 500 THEN 'High' ELSE 'Low' END AS loss_severity FROM daily_brand ORDER BY brand DESC, returned_date, hour_of_day
